CREATE TABLE IF NOT EXISTS project_capital_interests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, institution_id uuid NOT NULL REFERENCES institutional_profiles(id) ON DELETE CASCADE, interest_type text NOT NULL DEFAULT 'information_request', amount numeric(20,2), currency text NOT NULL DEFAULT 'NGN', message text, status text NOT NULL DEFAULT 'submitted', created_at timestamptz NOT NULL DEFAULT now());